const input = $input.first().json;
const q = input.query || {};
const pick = (k) => input[k] ?? q[k];

const parseIfString = (v) => {
  if (typeof v !== 'string') return v;
  const t = v.trim().replace(/^```(?:json)?\s*/,'').replace(/```\s*$/,'');
  try { return JSON.parse(t); } catch { return v; }
};

let chart_type = (pick('chart_type') || 'bar').toString().toLowerCase();
const title     = pick('title')   || 'Chart';
let labels      = parseIfString(pick('labels'));
let series      = parseIfString(pick('series'));
const x_label   = pick('x_label') || '';
const y_label   = pick('y_label') || '';

if (!Array.isArray(labels) || !Array.isArray(series) || !series.length) {
  throw new Error('create_chart needs: chart_type, title, labels (array), series (array of {name,values}). Got: ' + JSON.stringify({chart_type, labels_type: typeof labels, series_type: typeof series}));
}

let indexAxis;
if (chart_type === 'horizontalbar') { chart_type = 'bar'; indexAxis = 'y'; }
if (!['bar','line','pie','doughnut','scatter','radar','polarArea'].includes(chart_type)) chart_type = 'bar';

const palette = ['#4F46E5','#10B981','#F59E0B','#EF4444','#06B6D4','#8B5CF6','#EC4899','#84CC16'];
const isPieLike = chart_type === 'pie' || chart_type === 'doughnut';

const datasets = series.map((s, i) => {
  const vals = Array.isArray(s.values) ? s.values.map(v => typeof v === 'number' ? v : parseFloat(v)) : [];
  return {
    label: s.name || `Series ${i+1}`,
    data: vals,
    backgroundColor: isPieLike ? palette.slice(0, labels.length) : palette[i % palette.length],
    borderColor: palette[i % palette.length],
    borderWidth: chart_type === 'line' ? 2 : 1,
    tension: chart_type === 'line' ? 0.3 : undefined,
    fill: chart_type === 'line' ? false : undefined
  };
});

const chart = {
  type: chart_type,
  data: { labels, datasets },
  options: {
    responsive: true,
    indexAxis,
    plugins: {
      title: { display: true, text: title, font: { size: 16, weight: 'bold' } },
      legend: { display: datasets.length > 1 || isPieLike }
    },
    scales: isPieLike ? {} : {
      x: { title: { display: !!x_label, text: x_label } },
      y: { title: { display: !!y_label, text: y_label }, beginAtZero: true }
    }
  }
};

return [{ json: { backgroundColor: 'white', width: 800, height: 450, format: 'png', version: '4', chart } }];
